  'guide.activity_bookings_title': {'ru': 'Мои записи', 'en': 'My bookings', 'ka': 'ჩემი ჩანაწერები'},
  'guide.activity_bookings_desc': {'ru': 'Список сходок, в которых вы записаны участвовать.', 'en': "A list of meetups you're signed up to attend.", 'ka': 'შეხვედრების სია, რომლებშიც მონაწილეობისთვის ხართ ჩაწერილი.'},
  'guide.activity_favorites_title': {'ru': 'Избранное', 'en': 'Favorites', 'ka': 'რჩეულები'},
